// Merges scripts/descriptions.json (generated by gen-descriptions.mjs) into
// src/data.js: adds {what, useful} to every category and group, and turns
// each item string into {name, description}.
import { data } from "../src/data.js";
import { readFileSync, writeFileSync } from "fs";

const cache = JSON.parse(readFileSync(new URL("./descriptions.json", import.meta.url), "utf8"));

const missing = [];

const enriched = data.map((bucket) => ({
  name: bucket.name,
  categories: bucket.categories.map((category) => {
    const catCache = cache[category.name];
    if (!catCache) {
      missing.push(category.name);
      return category;
    }
    return {
      name: category.name,
      description: catCache.category,
      groups: category.groups.map((group) => {
        const groupCache = catCache.groups[group.heading];
        if (!groupCache) {
          missing.push(`${category.name} > ${group.heading}`);
          return group;
        }
        return {
          heading: group.heading,
          description: { what: groupCache.what, useful: groupCache.useful },
          items: group.items.map((item) => {
            const itemCache = groupCache.items[item];
            if (!itemCache) {
              missing.push(`${category.name} > ${group.heading} > ${item}`);
              return { name: item, description: null };
            }
            return { name: item, description: itemCache };
          }),
        };
      }),
    };
  }),
}));

if (missing.length > 0) {
  console.warn("Missing descriptions for:\n" + missing.map((m) => `  - ${m}`).join("\n"));
}

const out = `// 3 top-level buckets -> 16 original roadmap categories -> grouped topics,
// each with a short {what, useful} description generated via nemotron-3-ultra.
export const data = ${JSON.stringify(enriched, null, 2)};
`;

writeFileSync(new URL("../src/data.js", import.meta.url), out);
console.log("wrote src/data.js");